"""Generate the complete v4 report from saved evidence; never invent success claims."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];summary=json.loads((ROOT/'artifacts/benchmark-v4/summary.json').read_text());cal=json.loads((ROOT/'artifacts/evaluation-v4/calibration.json').read_text());meta=json.loads((ROOT/'artifacts/models/semantic-v4/metadata.json').read_text());full=summary['full_evaluation'];paired=summary['paired_evaluation'];labels=['rice','pasta','broccoli','chicken']
lines=['# Local semantic segmentation: v4 experiment','',f'Trained locally on **{meta["training_images"]:,} images** for {meta["epochs"]} epochs ({meta["training_seconds"]/60:.1f} minutes). Architecture: {meta["architecture"]}. New pixel-annotated training data increased chicken/duck examples from 269 to 748. No paid GPU was used.','', '## Fresh local evaluation: 110 images','', '| Model | Macro IoU | Chicken IoU | Chicken precision | Chicken presence recall | Chicken pixel recall | Chicken false positives | Other-food false alarms |','|---|---:|---:|---:|---:|---:|---:|---:|']
for name,v in full.items():
 c=v['per_class']['chicken'];lines.append(f'| {name} | {v["macro_iou"]:.1%} | {c["iou"]:.1%} | {c["precision"]:.1%} | {c["recall"]:.1%} | {c["pixel_recall"]:.1%} | {c["fp"]} | {v["negative_false_positives"]}/{v["negative_images"]} |')
lines+=['','| Food | v1 IoU | v3 IoU | v4 IoU | v1 recall | v3 recall | v4 recall | v4 pixel recall |','|---|---:|---:|---:|---:|---:|---:|---:|']
for l in labels:
 a,b,c=[full[n]['per_class'][l] for n in ['Original YOLO v1','Previous ensemble v3','Semantic v4']];lines.append(f'| {l} | {a["iou"]:.1%} | {b["iou"]:.1%} | {c["iou"]:.1%} | {a["recall"]:.1%} | {b["recall"]:.1%} | {c["recall"]:.1%} | {c["pixel_recall"]:.1%} |')
lines+=['','## Paired Gemini comparison: 32 new images','','| Model | Macro IoU | Chicken IoU | Chicken presence recall | Chicken pixel recall |','|---|---:|---:|---:|---:|']
for name,v in paired.items():
 c=v['per_class']['chicken'];lines.append(f'| {name} | {v["macro_iou"]:.1%} | {c["iou"]:.1%} | {c["recall"]:.1%} | {c["pixel_recall"]:.1%} |')
diff=paired['Semantic v4']['macro_iou']-paired['Gemini 4 Argon']['macro_iou'];ci=summary['paired_difference']['macro_iou_difference_95_percentile_interval']
lines+=['',f'Local minus Gemini macro-IoU difference: **{diff*100:+.1f} percentage points**, paired image-bootstrap 95% interval **[{ci[0]*100:+.1f}, {ci[1]*100:+.1f}]**. Gemini yielded {summary["gemini_parsed_outputs"]}/32 usable outputs. Failed geometry/transport outputs count as empty predictions.']
conditional=summary['valid_geometry_diagnostic'];lines+=['',f'Valid-Gemini-geometry diagnostic ({conditional["images"]} images): local macro IoU {conditional["local"]["macro_iou"]:.1%}, Gemini {conditional["gemini"]["macro_iou"]:.1%}. This excludes malformed/missing outputs only; wrong or empty but valid predictions remain. It is a diagnostic, not a replacement for the full predefined comparison.']
if ci[0]>0:lines+=['','This sample supports a local-model advantage on this specific public-data segmentation task. It does not establish general superiority or real cafeteria performance.']
else:lines+=['','**This experiment does not establish that the local model beats Gemini.** A higher point estimate alone, if present, is insufficient when the paired interval crosses zero.']
lines+=['','## Validation selection and recall guard','','| Food | Selected source | Threshold | Minimum component area | Presence recall floor | Pixel recall floor | All constraints met |','|---|---|---:|---:|---:|---:|---|']
for r in cal:
 s=r['selected'];lines.append(f'| {r["label"]} | {s["source"]} | {s["confidence"]:.2f} | {s["min_area_fraction"]:.2%} | {r["reference"]["recall"]:.1%} | {r["reference"]["pixel_recall"]:.1%} | {r["constraints_satisfied"]} |')
decision=json.loads((ROOT/'artifacts/evaluation-v4/model-selection.json').read_text())
lines+=['','## Training approach comparison (validation only)','','| Approach | Calibrated macro IoU | Calibrated chicken IoU | All constraints passed | Selection objective |','|---|---:|---:|---|---:|']
for c in decision['candidates']:
 v=c['validation'];lines.append(f'| {c["folder"]} | {v["macro_iou"]:.1%} | {v["per_class"]["chicken"]["iou"]:.1%} | {c["all_constraints_satisfied"]} | {c["objective"]:.4f} |')
lines+=['',f'Selected: **{decision["selected"]}**. {decision["selection"]}']
lines+=['','The threshold grid and objective were frozen before test scoring. Presence recall detects whether a food was found at all; pixel recall measures how much of its annotated region was recovered. Neither quantity is food mass. Validation constraints are not a guarantee on unseen plates.','', '## Limits and evidence','',summary['note'],'','The 110 images were reserved from unused publisher **training** data before training. All previous holdouts remain excluded. This new local split is not the official publisher test split. Independent pHash audit found no training-to-holdout near duplicates; unknown source clustering remains possible. FoodSeg103 chicken/duck labels cannot validate chicken-only species recognition.','',f'API accounting at v4 scoring: **${summary["accounted_total_usd"]:.6f} / $5**, including retained unknown-outcome reservations. The new 32 Gemini requests cost ${summary["gemini_cost_usd"]:.6f}. Training cost no API tokens. Unmeasured food weight stays explicitly unknown.','',f'Checkpoint SHA-256: `{meta["sha256"]}`. Raw predictions, per-image counts, paired bootstrap and cost evidence are in `artifacts/evaluation-v4/` and `artifacts/benchmark-v4/`. Portable results: [evaluation-v4-summary.json](evaluation-v4-summary.json). Training configuration and sources: [frozen protocol](EVALUATION_V4_PROTOCOL.md). Earlier benchmark comparisons are now regression evidence.']
(ROOT/'docs/EVALUATION_V4.md').write_text('\n'.join(lines)+'\n');print('Wrote docs/EVALUATION_V4.md')
